import * as T from '../three.module.min.js';
// Batch stationary scenery by material. Moving actors, flags and sprites stay separate.
export function batchScenery(root){root.updateWorldMatrix(true,true);const inverse=root.matrixWorld.clone().invert(),buckets=new Map(),meshes=[];root.traverse(o=>{if(o.isMesh&&o.material?.isMeshStandardMaterial&&!Array.isArray(o.material)&&!o.material.map){const key=[o.material.color.getHex(),o.material.roughness,o.material.metalness,o.material.side].join(':');if(!buckets.has(key))buckets.set(key,{material:o.material,parts:[]});const geo=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();geo.applyMatrix4(inverse.clone().multiply(o.matrixWorld));buckets.get(key).parts.push(geo);meshes.push(o);}});for(const o of meshes)o.removeFromParent();for(const {material,parts} of buckets.values()){const total=parts.reduce((s,g)=>s+g.attributes.position.array.length,0),p=new Float32Array(total),n=new Float32Array(total);let offset=0;for(const g of parts){if(!g.attributes.normal)g.computeVertexNormals();p.set(g.attributes.position.array,offset);n.set(g.attributes.normal.array,offset);offset+=g.attributes.position.array.length;g.dispose();}const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(p,3));g.setAttribute('normal',new T.BufferAttribute(n,3));g.computeBoundingSphere();const m=new T.Mesh(g,material);m.castShadow=true;m.receiveShadow=true;root.add(m);}return root;}
